"""Anno 1503 Auto Trainer V0.11.0 - transactional updater v3.

Updater architecture release. Future updates are fully patched, compiled and built
while the currently working EXE remains open. Only an already prepared candidate
is allowed to close the old trainer. Commit has startup healthcheck, rollback and
failed-release quarantine.

No gameplay, goods, money or speed calibration logic is changed in this release.
"""
from pathlib import Path
import ast
import base64

VERSION = "0.11.0"
UPDATER_B64 = ''
FINISH_METHOD = '    def _finish_close_when_safe(self):\n        speed_alive=bool(self.speed_thread and self.speed_thread.is_alive())\n        freeze_alive=bool(self.freeze_thread and self.freeze_thread.is_alive())\n        if speed_alive or freeze_alive:\n            self.root.after(75,self._finish_close_when_safe)\n            return\n        try:\n            core.make_result_zip(force=True)\n        except Exception:\n            pass\n        try:\n            if self.hproc:\n                core.kernel32.CloseHandle(self.hproc)\n                self.hproc=None\n        except Exception:\n            pass\n        try:\n            core.close_run_logging()\n        except Exception:\n            pass\n\n        update_script=self.pending_update_script\n        if update_script:\n            try:\n                app_updater.launch_apply_script(update_script)\n            except Exception as exc:\n                self.pending_update_script=None\n                self.closing=False\n                try:\n                    self.update_status_var.set("Update: Commit-Worker konnte nicht starten; Trainer bleibt offen")\n                    self.update_btn.configure(state="normal")\n                    self._set_speed_buttons(True)\n                    messagebox.showerror(\n                        "Anno 1503 Update",\n                        f"Update wurde NICHT aktiviert. Der aktuelle Trainer bleibt offen.\\n\\n{exc}"\n                    )\n                except Exception:\n                    pass\n                return\n\n        self.root.destroy()\n        if update_script:\n            os._exit(0)\n'


def _replace_version_markers(path: Path, old: str, new: str):
    text=path.read_text(encoding="utf-8")
    pairs=[
        (f'TRAINER_VERSION = "{old}"', f'TRAINER_VERSION = "{new}"'),
        (f' AUTO TRAINER V{old}', f' AUTO TRAINER V{new}'),
        (f'Anno 1503 Auto Trainer V{old} PERMANENT BOOTSTRAP', f'Anno 1503 Auto Trainer V{new} PERMANENT BOOTSTRAP'),
        (f'"version":"{old}"', f'"version":"{new}"'),
        (f'"version": "{old}"', f'"version": "{new}"'),
    ]
    for a,b in pairs:
        if a in text:
            text=text.replace(a,b)
    path.write_text(text,encoding="utf-8")


def _replace_method(path: Path, method_name: str, replacement: str):
    text=path.read_text(encoding="utf-8")
    tree=ast.parse(text,filename=path.name)
    candidates=[]
    for node in ast.walk(tree):
        if isinstance(node,(ast.FunctionDef,ast.AsyncFunctionDef)) and node.name==method_name:
            candidates.append(node)
    if len(candidates)!=1:
        raise RuntimeError(f"Expected exactly one {method_name} in {path.name}, found {len(candidates)}")
    node=candidates[0]
    lines=text.splitlines(keepends=True)
    start=node.lineno-1
    end=node.end_lineno
    repl=replacement.rstrip()+"\n\n"
    path.write_text("".join(lines[:start])+repl+"".join(lines[end:]),encoding="utf-8")


def apply(root):
    root=Path(root)
    core=root/"Anno1503_AutoTrainer.py"
    gui=root/"Anno1503_AutoTrainer_GUI.py"
    updater=root/"updater.py"
    for p in (core,gui,updater):
        if not p.is_file():
            raise RuntimeError(f"Required source file missing: {p}")

    core_text=core.read_text(encoding="utf-8")
    if 'TRAINER_VERSION = "0.10.11"' not in core_text:
        raise RuntimeError("V0.11.0 expects a clean V0.10.11 source base")

    _replace_version_markers(core,"0.10.11","0.11.0")
    _replace_version_markers(gui,"0.10.11","0.11.0")

    g=gui.read_text(encoding="utf-8")
    old_status="V0.10.11: Session-Cache; Vollscans bei gleicher Anno-Sitzung vermeiden …"
    if old_status in g:
        g=g.replace(old_status,"V0.11.0: transaktionaler Updater V3; alter Trainer bleibt bis zum fertigen Build offen …",1)
    gui.write_text(g,encoding="utf-8")

    _replace_method(gui,"_finish_close_when_safe",FINISH_METHOD)
    updater.write_bytes(base64.b64decode(UPDATER_B64))

    (root/"CHANGELOG_V0_11_0.md").write_text(
        "# V0.11.0 - Transactional Updater V3\n\n"
        "- Patch, py_compile und PyInstaller-Build laufen komplett, solange die alte EXE weiter offen bleibt.\n"
        "- Der Trainer schliesst erst, wenn eine fertige neue EXE plus vorbereitete Source vorliegen.\n"
        "- Commit-Worker wird vor dem Schliessen syntaxgeprueft und muss nach Start weiterlaufen.\n"
        "- Neue EXE muss einen versionsgebundenen Startup-Healthcheck liefern und danach stabil weiterlaufen.\n"
        "- Healthcheck-/Commitfehler: automatischer Rollback auf alte Source+EXE und Neustart der alten Version.\n"
        "- Fehlgeschlagener identischer Release-Fingerprint wird quarantiniert, daher keine Update-Endlosschleife.\n"
        "- Keine Aenderung an Gameplay-, Waren-, Geld- oder Speed-Logik.\n",
        encoding="utf-8"
    )
